import {recipes,topics,articles,constitutions,quizQuestions,quizOptions,sources,lifestyle} from './data.js';
import {getAgentReply} from './agent.js';
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',leaf:'<path d="M20 3c-9-1-16 3-16 10a7 7 0 0 0 7 7C18 20 21 12 20 3Z"/><path d="m4 21 11-12"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',spark:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13Z"/>',wind:'<path d="M3 8h12a3 3 0 1 0-3-3M3 12h15a3 3 0 1 1-3 3M3 16h5"/>',scale:'<path d="M4 5h16v16H4z"/><path d="M8 9a5 5 0 0 1 8 0M12 8v3"/>',bowl:'<path d="M3 12h18c0 6-5 8-9 8s-9-2-9-8Z"/><path d="M7 5v3m5-5v5m5-3v3"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',back:'<path d="m14 5-7 7 7 7"/>',book:'<path d="M3 3h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v17h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3zM12 5v17"/>',cup:'<path d="M4 7h13v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5zM17 8h2a3 3 0 0 1 0 6h-2M7 3v1m4-1v1m4-1v1"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.leaf}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultProfile={name:'体验用户',goal:'均衡饮食',habit:'自己做饭与外食都有',preference:'暂无偏好',constitution:'',updated:''};
function readStore(){try{const s=JSON.parse(localStorage.getItem('zhiyang-demo-v1'));return{profile:{...defaultProfile,...(s?.profile&&typeof s.profile==='object'?s.profile:{})},saved:Array.isArray(s?.saved)?s.saved.filter(x=>typeof x==='string'):[],plans:Array.isArray(s?.plans)?s.plans.filter(x=>x&&typeof x.id==='string'&&Array.isArray(x.meals)):[]}}catch{return{profile:{...defaultProfile},saved:[],plans:[]}}}
let state=readStore(),page='home',foodTab='全部',careTab='全部',day='今日',homeMode='三餐',quizStep=0,quizAnswers=[],toastTimer,chatBusy=false,chatScenario='general',history=[],chatVersion=0;
let pendingPlans=new Map();
const main=document.getElementById('main'),detail=document.getElementById('detail-dialog'),chat=document.getElementById('chat-dialog');
function persist(){try{localStorage.setItem('zhiyang-demo-v1',JSON.stringify(state));return true}catch{toast('本浏览器无法保存，当前修改仅本次有效');return false}}
function toast(s){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
function heading(title,sub,english='YOUR WELLNESS SPACE'){return`<div class="page-heading"><div><p class="eyebrow">${english}</p><h1>${title}</h1><p>${sub}</p></div><div class="date-stamp"><strong>09<span>/12</span></strong><span>演示日期 · 白露时节</span></div></div>`}
function sectionHead(title,label,button=''){return`<div class="section-heading"><div><span class="eyebrow">${label}</span><h2>${title}</h2></div>${button}</div>`}
function recipeCard(r,compact=false){return`<button class="recipe-tile ${compact?'compact':''}" data-recipe="${r.id}">${r.image?`<img src="${r.image}" alt="${r.title}食物示意" loading="lazy">`:`<div class="recipe-type-art ${r.id==='breakfast'?'amber':''}">${icon(r.id==='tea'?'cup':'bowl')}<span>${r.time}</span></div>`}<div class="recipe-tile-body"><span class="tag">${r.tag}</span><h3>${r.title}</h3><p>${r.desc}</p><div class="recipe-meta"><span>${r.duration}</span><span>查看搭配 ${icon('arrow')}</span></div></div></button>`}
function topicCard(t){return`<button class="topic-card" data-topic="${t.id}"><span class="topic-symbol ${t.accent}">${icon(t.icon)}</span><span><strong>${t.title}</strong><small>${t.subtitle}</small></span>${icon('arrow')}</button>`}
function articleCard(a){return`<button class="article-card" data-article="${a.id}"><img src="${a.image}" alt="${a.label}配图" loading="lazy"><div><span class="article-label">${a.label}</span><h3>${a.title}</h3><span class="small muted">${a.read}阅读 · 内容示例</span></div></button>`}
function profileMini(){return`<section class="profile-card"><div class="section-mini"><span>我的健康档案</span>${icon('user')}</div><span class="subtle-label">${state.profile.constitution?'已保存测评流程的模拟结果':'先了解你，再给建议'}</span><h2>${state.profile.constitution?esc(state.profile.constitution)+' · 示例':'从认识自己开始'}</h2><p>当前目标：${esc(state.profile.goal)}<br>让每一次建议，更贴近生活。</p><div class="profile-tags"><span>${esc(state.profile.goal)}</span><span>${state.profile.constitution?'模拟体质卡':'尚未正式测评'}</span></div><button class="outline-button" data-page="profile">${state.profile.updated?'查看我的档案':'完善我的档案'} ${icon('arrow')}</button></section>`}
function home(){return`${heading('今天，也好好照顾自己。','从一顿好饭，一杯温饮开始。','GOOD DAY, GOOD HEALTH')}<div class="hero-grid"><section class="ai-hero"><span class="ai-label">${icon('spark')} 知养 AI · 你的食养助手</span><h2>最近身体怎么样？<br>和知养聊一聊</h2><p>饮食、体重、作息，把你的想法告诉我。</p><button class="hero-input" data-chat="">我最近胖了，三餐应该怎么吃？<span>${icon('arrow')}</span></button><div class="hero-prompts"><button data-chat="我想健康减重">健康减重</button><button data-chat="我想健康增重">健康增重</button><button data-chat="推荐一杯养生茶">食养茶饮</button><button data-chat="我最近作息有点乱">作息调整</button></div></section>${profileMini()}</div><section class="section">${sectionHead('今天，怎么吃怎么过','EVERYDAY NOURISHMENT',`<div class="segmented" aria-label="三餐与起居"><button class="${homeMode==='三餐'?'active':''}" data-home-mode="三餐">三餐</button><button class="${homeMode==='起居'?'active':''}" data-home-mode="起居">起居</button></div>`)}${homeMode==='三餐'?`<div class="daily-meals">${[['breakfast','早餐','07:30','一碗热粥，唤醒早晨'],['lunch','午餐','12:00','荤素搭配，好好吃饭'],['dinner','晚餐','18:30','家常食材，简单吃好']].map(([id,label,time,title],i)=>`<button class="daily-meal" data-recipe="${id}"><div class="meal-badge ${i===1?'midday':i===2?'evening':''}">${icon(i===2?'moon':i===1?'sun':'bowl')}</div><div><span class="meal-time">${label} <span>· ${time} 示例</span></span><h3>${title}</h3><p>${recipes.find(r=>r.id===id).title}</p></div>${icon('arrow')}</button>`).join('')}</div>`:`<div class="routine-card"><span class="routine-icon">${icon('moon')}</span><div><span class="subtle-label">晚间起居参考</span><h3>给忙碌的一天，留一点空白。</h3><p>选择你自己的睡前准备时间，先完成一件小事。</p></div><button class="outline-button" data-lifestyle="sleep">查看建议 ${icon('arrow')}</button></div>`}</section><div class="home-lower"><section class="section">${sectionHead('食养灵感','A LITTLE NOURISHMENT',`<button class="text-button" data-page="food">全部 ${icon('arrow')}</button>`)}<div class="nourish-grid">${recipeCard(recipes.find(r=>r.id==='tea'),true)}${recipeCard(recipes.find(r=>r.id==='lunch'),true)}</div></section><section class="section">${sectionHead('最近，你在意什么','TAKE CARE OF YOURSELF',`<button class="text-button" data-page="care">更多 ${icon('arrow')}</button>`)}<div class="topic-list">${topics.slice(0,4).map(topicCard).join('')}</div></section></div><section class="section">${sectionHead('慢慢读，好好养','WELLNESS JOURNAL',`<button class="text-button" data-food-tab="文章">全部文章 ${icon('arrow')}</button>`)}<div class="article-grid">${articles.map(articleCard).join('')}</div></section>`}
function food(){const options=['全部','三餐搭配','食养茶饮','起居建议','文章'];const visible=recipes.filter(r=>foodTab==='全部'||r.category===foodTab);return`${heading('一日三餐，一点食养。','把适合自己的搭配，慢慢放进生活。','FOOD & EVERYDAY LIVING')}<div class="food-banner"><img src="assets/lunch.jpg" alt="中式三餐搭配示意"><div><span class="subtle-label">从家常饭开始</span><h2>好好吃饭，是每天的小事。</h2><p>食谱、茶饮和起居参考，<br>也可以交给知养一起帮你选。</p><button class="primary-button" data-chat="帮我安排一日三餐">${icon('spark')} 帮我安排三餐</button></div></div><div class="filter-row" aria-label="食养分类">${options.map(x=>`<button data-food-tab="${x}" class="filter-chip ${foodTab===x?'active':''}" aria-pressed="${foodTab===x}">${x}</button>`).join('')}</div>${foodTab==='三餐搭配'?`<div class="inline-heading"><h2>${day}三餐参考</h2><div class="segmented"><button data-day="今日" class="${day==='今日'?'active':''}">今日</button><button data-day="明日" class="${day==='明日'?'active':''}">明日</button></div></div><p class="muted section-note">示例安排，可按你的偏好替换；份量未做个人计算。</p>`:''}${foodTab==='文章'?`<div class="article-grid">${articles.map(articleCard).join('')}</div>`:foodTab==='起居建议'?`<div class="routine-card"><span class="routine-icon">${icon('moon')}</span><div><span class="tag">晚间起居</span><h3>${lifestyle.title}</h3><p>${lifestyle.desc}</p></div><button class="primary-button" data-lifestyle="sleep">查看建议</button></div>`:`<div class="food-grid">${(foodTab==='三餐搭配'&&day==='明日'?[recipes[4],recipes[2],recipes[1]]:visible).map(r=>recipeCard(r)).join('')}</div>`}<div class="small-notice">${icon('book')} 本页为内容与交互示例。可在详情中查看参考来源和适用说明。</div>`}
function care(){const groups=['全部','日常状态','呼吸与咽喉','脾胃与消化','作息与情绪'];return`${heading('身体的小信号，认真听。','从你的感受出发，看看日常生活可以怎样调整。','CARE & DAILY WELLBEING')}<div class="care-intro"><span class="care-intro-icon">${icon('heart')}</span><div><h2>日常调养，也要有分寸。</h2><p>以下为一般生活、饮食与休息参考，不用于诊断或治疗。<br>涉及医疗用途，请咨询医生；持续或明显不适时，优先寻求专业帮助。</p></div><button class="outline-button" data-chat="我想聊聊最近的身体感受">${icon('spark')} 和助手聊聊</button></div><section class="section">${sectionHead('当下热门','COMMON CONCERNS')}<div class="filter-row">${groups.map(x=>`<button class="filter-chip ${careTab===x?'active':''}" data-care-tab="${x}" aria-pressed="${careTab===x}">${x}</button>`).join('')}</div><div class="care-grid">${topics.filter(t=>careTab==='全部'||t.group===careTab).map(t=>`<button class="care-tile" data-topic="${t.id}"><span class="topic-symbol ${t.accent}">${icon(t.icon)}</span><span class="small muted">${t.group}</span><h3>${t.title}</h3><p>${t.subtitle}</p><span class="meal-link">生活建议 · 食养参考 ${icon('arrow')}</span></button>`).join('')}</div></section><div class="feature-line"><div><span class="eyebrow">KNOW YOURSELF</span><h3>湿气重，就是痰湿质吗？</h3><p>日常感受与正式体质判定有区别。先了解九种基本类型。</p></div><button class="outline-button" data-action="constitutions">了解九种体质 ${icon('arrow')}</button></div>`}
function planCard(p){return`<article class="saved-plan"><div class="section-mini"><span>${esc(p.goal)} · 方案示例</span><button class="icon-button" data-remove-plan="${esc(p.id)}" aria-label="移除${esc(p.title)}">${icon('close')}</button></div><h3>${esc(p.title)}</h3><dl>${p.meals.map(m=>`<div><dt>${esc(m.label)}</dt><dd>${esc(m.value)}</dd></div>`).join('')}</dl><p class="small muted">${esc(p.note)}</p><button class="text-button" data-chat="${esc(p.goal==='规律作息'?'调整我的作息安排':p.goal==='健康增重'?'我想调整增重方案':p.goal==='均衡饮食'?'我想调整三餐':'我想调整减重方案')}">和助手一起调整 ${icon('arrow')}</button></article>`}
function profile(){const p=state.profile;return`${heading('更了解你，才能更贴近你。','你的档案、收藏和方案，放在一起。','MY WELLNESS SPACE')}<section class="profile-overview"><span class="big-avatar">${esc((p.name||'养').slice(0,1))}</span><div><span class="subtle-label">个人档案 · 本地演示</span><h2>${esc(p.name)}</h2><p>${esc(p.goal)} · ${esc(p.habit)}</p></div><button class="outline-button" data-action="edit-profile">编辑档案</button></section><div class="profile-sections"><section class="constitution-panel"><div class="section-mini"><span>我的体质</span><span class="tag">${p.constitution?'模拟结果':'尚未正式测评'}</span></div><h2>${p.constitution?esc(p.constitution):'每个人，都有自己的节奏。'}</h2><p>${p.constitution?'此卡由五题演示流程生成，固定展示平和质，不是你的体质判定。':'先了解九种基本类型，再体验体质测评的页面流程。'}</p><div class="button-row"><button class="primary-button" data-action="quiz">${p.constitution?'重新体验测评':'体验体质测评'} ${icon('arrow')}</button><button class="text-button" data-action="constitutions">九种体质科普</button></div><span class="small muted">五题为交互示例，不是标准量表。</span></section><section class="preferences-panel"><span class="subtle-label">我希望，养成这样的生活</span><h3>${esc(p.goal)}</h3><div class="preference-row"><span>用餐习惯</span><strong>${esc(p.habit)}</strong></div><div class="preference-row"><span>饮食偏好</span><strong>${esc(p.preference)}</strong></div><button class="text-button" data-action="edit-profile">调整我的偏好 ${icon('arrow')}</button></section></div><section class="section">${sectionHead('我的方案','MY PLANS',`<span class="count-label">${state.plans.length} 份</span>`)}${state.plans.length?`<div class="plans-grid">${state.plans.map(planCard).join('')}</div>`:`<div class="empty-state">${icon('spark')}<div><h3>从一次咨询开始</h3><p>让助手给出方案，点击保存，就能在这里继续查看。</p></div><button class="outline-button" data-chat="我想健康减重">体验一次咨询</button></div>`}</section><section class="section">${sectionHead('我的收藏','SAVED FOR LATER',`<span class="count-label">${state.saved.length} 项</span>`)}${state.saved.length?`<div class="saved-grid">${state.saved.map(key=>{const [type,id]=key.split(':');const item=(type==='recipe'?recipes:articles).find(x=>x.id===id);return item?`<button class="saved-item" data-${type}="${id}">${icon(type==='recipe'?'bowl':'book')}<span>${esc(item.title)}</span>${icon('arrow')}</button>`:''}).join('')}</div>`:`<p class="empty-copy">喜欢的食谱、茶饮和文章，可以先收藏，慢慢看。</p>`}</section><div class="privacy-line"><p>演示档案仅保存在当前浏览器，未上传服务器。无需填写真实敏感信息。</p><button class="text-button" data-action="reset">清除本地演示数据</button></div>`}
function render(){document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page&&b.classList.contains('nav-item'));if(b.classList.contains('nav-item'))b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});main.innerHTML=({home,food,care,profile}[page]||home)();document.querySelector('.topbar-label').textContent=matchMedia('(max-width:760px)').matches?'知养':'你的日常食养空间';paintIcons();}
function navigate(next,replace=false){if(!['home','food','care','profile'].includes(next))return;page=next;render();historyAPI(replace);window.scrollTo({top:0,behavior:'instant'});}
function historyAPI(replace){window.history[replace?'replaceState':'pushState']({},'',`#${page}`)}
window.addEventListener('popstate',()=>{page=location.hash.slice(1)||'home';if(!['home','food','care','profile'].includes(page))page='home';render()});
function detailHeader(label){return`<div class="dialog-toolbar"><span>${label}</span><button class="icon-button" data-close="detail" aria-label="关闭详情">${icon('close')}</button></div>`}
function openDetail(html,label='内容详情'){document.getElementById('detail-content').innerHTML=detailHeader(label)+html;detail.setAttribute('aria-label',label);if(!detail.open)detail.showModal();detail.scrollTop=0;}
const sourceHtml=(key)=>sources[key]?`<details class="source-details"><summary>参考来源与内容说明</summary><p>页面文案为 Demo 编排示例，未经过完整专业审核。下列来源提供相关一般原则，不是对本方案的验证。</p><a href="${sources[key].url}" target="_blank" rel="noopener noreferrer">${sources[key].title} ↗</a></details>`:'';
function recipeDetail(id){const r=recipes.find(x=>x.id===id);if(!r)return;const saved=state.saved.includes('recipe:'+id);openDetail(`${r.image?`<img class="detail-cover" src="${r.image}" alt="${r.title}示意图">`:''}<div class="detail-body"><span class="tag">${r.category} · 示例</span><h2>${r.title}</h2><p class="detail-lead">${r.desc}</p><div class="detail-meta">${icon('clock')} ${r.duration}<span>·</span>日常食养参考</div><h3>准备这些食材</h3><div class="ingredient-list">${r.ingredients.map(x=>`<span>${x}</span>`).join('')}</div><h3>可以这样搭配</h3><ol class="step-list">${r.steps.map(x=>`<li>${x}</li>`).join('')}</ol><div class="gentle-note">${r.note}</div>${sourceHtml(r.source)}<div class="detail-actions"><button class="primary-button" data-detail-chat="${r.id==='tea'?'推荐一杯养生茶':`这道${r.title}怎么加入我的三餐？`}">${icon('spark')} 结合我的情况问问 AI</button><button class="outline-button" data-save="recipe:${r.id}">${icon('bookmark')} ${saved?'已收藏':'收藏'}</button></div></div>`,'食养详情')}
function topicDetail(id){const t=topics.find(x=>x.id===id);if(!t)return;openDetail(`<div class="detail-body"><span class="topic-symbol ${t.accent}">${icon(t.icon)}</span><span class="tag">${t.group} · 专题示例</span><h2>${t.title}</h2><p class="detail-lead">${t.subtitle}</p><div class="boundary-note"><strong>先看适用边界</strong><p>${t.boundary}</p></div><h3>日常生活可以先留意</h3><ol class="step-list">${t.tips.map(x=>`<li>${x}</li>`).join('')}</ol>${t.related?`<h3>相关食养灵感</h3><p class="small muted">仅为内容关联示例，不代表对这一症状有效。</p><button class="related-card" data-recipe="${t.related}">${icon('bowl')}<span>${recipes.find(r=>r.id===t.related).title}</span>${icon('arrow')}</button>`:''}${sourceHtml(t.source)}<div class="detail-actions"><button class="primary-button" data-detail-chat="${t.title}">${icon('spark')} 把我的情况告诉 AI</button></div></div>`,'日常调养')}
function articleDetail(id){const a=articles.find(x=>x.id===id);if(!a)return;openDetail(`<img class="detail-cover" src="${a.image}" alt="${a.label}配图"><article class="detail-body article-body"><span class="tag">${a.label}</span><h2>${a.title}</h2><p class="small muted">知养内容示例 · ${a.read}阅读</p><p class="detail-lead">${a.intro}</p>${a.paragraphs.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}${sourceHtml(a.source)}<div class="detail-actions"><button class="primary-button" data-detail-chat="如何把${a.label}用到我的一日三餐？">${icon('spark')} 和助手聊聊这篇文章</button><button class="outline-button" data-save="article:${a.id}">${icon('bookmark')} ${state.saved.includes('article:'+id)?'已收藏':'收藏'}</button></div></article>`,'食养文章')}
function lifestyleDetail(){openDetail(`<div class="detail-body"><span class="topic-symbol purple">${icon('moon')}</span><span class="tag">起居建议</span><h2>${lifestyle.title}</h2><p class="detail-lead">${lifestyle.desc}</p><ol class="step-list">${lifestyle.points.map(p=>`<li>${p}</li>`).join('')}</ol><div class="gentle-note">安排要符合你的真实作息。持续睡眠困扰应寻求专业帮助。</div><button class="primary-button" data-detail-chat="帮我调整作息">${icon('spark')} 帮我安排今晚</button></div>`,'晚间起居')}
function editProfile(){const p=state.profile;openDetail(`<div class="detail-body"><span class="tag">仅在本浏览器保存</span><h2>让建议，更贴近你的生活</h2><p class="detail-lead">这里可以使用虚构信息体验，不必填写真实健康资料。</p><form id="profile-form"><label class="form-label">怎么称呼你<input name="name" maxlength="20" value="${esc(p.name)}" required autocomplete="off"></label><label class="form-label">当前最想关注的目标<select name="goal">${['均衡饮食','健康减重','健康增重','规律作息'].map(v=>`<option ${v===p.goal?'selected':''}>${v}</option>`).join('')}</select></label><label class="form-label">平时怎样吃饭<select name="habit">${['自己做饭与外食都有','主要自己做饭','主要在外吃饭'].map(v=>`<option ${v===p.habit?'selected':''}>${v}</option>`).join('')}</select></label><label class="form-label">饮食偏好<select name="preference">${['暂无偏好','偏爱家常中餐','更喜欢清淡口味','不喜欢吃鱼'].map(v=>`<option ${v===p.preference?'selected':''}>${v}</option>`).join('')}</select></label><p class="small muted">此处没有采集疾病、用药和过敏史，也不会据此生成真实个人处方。</p><button class="primary-button full-button" type="submit">保存档案 ${icon('check')}</button></form></div>`,'编辑我的档案')}
function constitutionList(){openDetail(`<div class="detail-body"><span class="tag">体质科普</span><h2>认识中医九种体质</h2><p class="detail-lead">以下是九种基本类型。下面的提示词仅帮助浏览，不是诊断依据，也不能靠单个感受给自己定型。</p><div class="constitution-grid">${constitutions.map(([n,d],i)=>`<div class="constitution-type"><span>${String(i+1).padStart(2,'0')}</span><h3>${n}</h3><p>${d}</p></div>`).join('')}</div><p class="gentle-note">“湿气重”是日常描述，不等于已经判定为“痰湿质”。正式判定应使用完整标准量表及相应计分方法。</p>${sourceHtml('constitution')}<button class="primary-button full-button" data-action="quiz">体验五题测评流程 ${icon('arrow')}</button></div>`,'中医九种体质')}
function quiz(){if(quizStep>=quizQuestions.length){openDetail(`<div class="detail-body quiz-result"><span class="tag">模拟结果 · 非个人判定</span><div class="result-symbol">示</div><h2>你的体质卡，会在这里呈现</h2><div class="sample-result"><span>结果页示例</span><h3>平和质</h3><p>已完成 ${quizAnswers.length} / 5 道流程演示题</p></div><p class="detail-lead">这五道问题不是正式体质量表。无论如何选择，本 Demo 都固定用“平和质”展示结果页，不进行体质计算。</p><div class="button-row"><button class="primary-button" data-action="save-quiz">保存示例体质卡</button><button class="outline-button" data-action="constitutions">了解九种类型</button></div></div>`,'测评结果页示例');return}openDetail(`<div class="detail-body"><span class="tag">五题交互演示 · 非正式量表</span><h2>认识自己的身体感受</h2><p class="small muted">正式量表与算法后续接入；当前选择仅用于体验页面。</p><div class="quiz-progress"><span>第 ${quizStep+1} 题 / 5 题</span><span>${Math.round(quizStep/5*100)}%</span></div><div class="progress-track"><span style="width:${quizStep/5*100}%"></span></div><h3 class="quiz-question">${quizQuestions[quizStep]}</h3><div class="quiz-options">${quizOptions[quizStep].map((o,i)=>`<button data-quiz-answer="${i}"><span>${o}</span>${icon('arrow')}</button>`).join('')}</div>${quizStep?'<button class="text-button" data-action="quiz-back">← 上一题</button>':''}<p class="small muted quiz-footnote">你的回答不会产生真实体质结论。</p></div>`,'体质测评流程')}
function about(){openDetail(`<div class="detail-body"><span class="tag">知养 · 交互 Demo 01</span><h2>先体验，再慢慢养成。</h2><p class="detail-lead">这是一个健康养生产品原型，你可以体验首页、AI 咨询、食养内容、调养专题、档案和方案保存。</p><div class="about-list"><p><strong>AI 咨询：</strong>目前是预设回复，可体验减重、增重、茶饮、作息、咽喉和排便等场景。尚未调用真实模型。</p><p><strong>体质测评：</strong>只有五题页面演示，固定展示示例结果，不是标准量表。</p><p><strong>演示数据：</strong>档案、收藏和方案仅保存在当前浏览器，可在“我的”中清除。聊天在页面刷新后清空。</p><p><strong>健康内容：</strong>为模拟体验准备，尚未经过完整专业审核；图片为 AI 生成的示意图。</p></div><button class="primary-button full-button" data-close="detail">开始体验</button></div>`,'关于这个 Demo')}
function toggleSave(key){const [type,id]=key.split(':');if(!(type==='recipe'?recipes:articles).some(x=>x.id===id))return;const i=state.saved.indexOf(key);if(i>=0)state.saved.splice(i,1);else state.saved.push(key);persist();toast(i>=0?'已取消收藏':'已收藏，可在“我的”中查看');document.querySelectorAll('[data-save]').forEach(b=>{if(b.dataset.save===key)b.innerHTML=icon('bookmark')+(i>=0?' 收藏':' 已收藏')});render()}
function openChat(query=''){if(detail.open)detail.close();if(!document.getElementById('chat-messages')){document.getElementById('chat-content').innerHTML=`<div class="chat-header"><span class="chat-avatar">${icon('spark')}</span><div><h2>知养 AI</h2><p>饮食 · 体重 · 作息 · 日常食养</p></div><button class="icon-button" data-action="new-chat" aria-label="重新开始对话">${icon('book')}</button><button class="icon-button" data-close="chat" aria-label="关闭咨询">${icon('close')}</button></div><div class="chat-demo-note">模拟对话 · 使用预设回复，尚未接入真实模型</div><div id="chat-messages" class="chat-messages" role="log" aria-label="咨询对话" aria-live="polite"><div class="welcome"><span>${icon('spark')}</span><h3>今天，想从哪里开始？</h3><p>把你的想法告诉我，<br>一起看看饮食与生活可以怎么调整。</p><div class="welcome-grid">${[['我最近胖了，应该怎么吃？','我想健康减重'],['想增重，三餐怎么安排？','我想健康增重'],['有什么适合日常喝的茶？','推荐一杯养生茶'],['作息有点乱，怎么调整？','我最近作息有点乱']].map(([t,q])=>`<button data-chat-send="${q}">${t} ${icon('arrow')}</button>`).join('')}</div><p class="small muted">当前档案目标：${esc(state.profile.goal)}</p></div></div><form id="chat-form" class="chat-compose"><label class="sr-only" for="chat-input">输入你想咨询的问题</label><textarea id="chat-input" maxlength="1500" rows="1" placeholder="比如：我最近胖了，三餐怎么安排？"></textarea><button type="submit" aria-label="发送咨询" id="chat-submit">${icon('arrow')}</button></form><p class="chat-footer-note">日常食养参考，医疗问题请咨询医生。</p>`}chat.setAttribute('aria-label','知养 AI 模拟咨询');if(!chat.open)chat.showModal();if(query)send(query);else if(matchMedia('(min-width:761px)').matches)document.getElementById('chat-input').focus()}
function appendMessage(type,html){const el=document.createElement('div');el.className=`message ${type}`;el.innerHTML=type==='assistant'?`<span class="message-avatar">${icon('spark')}</span><div class="message-body">${html}</div>`:`<div class="user-bubble">${html}</div>`;document.getElementById('chat-messages').append(el);el.scrollIntoView({block:'end'});return el}
async function send(text){text=String(text).trim().slice(0,1500);if(!text||chatBusy)return;document.querySelector('.welcome')?.remove();const input=document.getElementById('chat-input');if(input)input.value='';appendMessage('user',esc(text));history.push({role:'user',content:text});chatBusy=true;document.getElementById('chat-submit').disabled=true;const loading=appendMessage('assistant','<span class="typing"><i></i><i></i><i></i></span>');const current=chatVersion;
 try{const reply=await getAgentReply({message:text,profile:state.profile,history,scenario:chatScenario});if(current!==chatVersion)return;loading.remove();chatScenario=reply.scenario;let content=`<p>${esc(reply.text).replace(/\n/g,'<br>')}</p>`;if(reply.plan){if(state.profile.preference==='不喜欢吃鱼')reply.plan.meals=reply.plan.meals.map(m=>({...m,value:m.value.replace('清蒸鱼','菌菇豆腐')}));pendingPlans.set(reply.plan.id,reply.plan);content+=`<div class="chat-plan"><span class="tag">个人方案 · 模拟示例</span><h3>${reply.plan.title}</h3><dl>${reply.plan.meals.map(m=>`<div><dt>${m.label}</dt><dd>${esc(m.value)}</dd></div>`).join('')}</dl><p class="small muted">${esc(reply.plan.note)}</p><button class="primary-button" data-save-plan="${reply.plan.id}">${icon('bookmark')} 保存到我的方案</button></div>`}if(reply.recipes?.length)content+=`<div class="chat-recipes">${reply.recipes.map(id=>{const r=recipes.find(x=>x.id===id);return`<button data-chat-recipe="${id}">${r.image?`<img src="${r.image}" alt="${r.title}示意">`:`<span class="chat-recipe-icon">${icon('bowl')}</span>`}<span><strong>${r.title}</strong><small>${r.tag} · 查看详情</small></span>${icon('arrow')}</button>`}).join('')}</div>`;if(reply.topic)content+=`<button class="outline-button" data-chat-topic="${reply.topic}">查看相关专题 ${icon('arrow')}</button>`;if(reply.constitution)content+='<button class="outline-button" data-chat-constitution>了解九种体质</button>';if(reply.choices)content+=`<div class="chat-choices">${reply.choices.map(c=>`<button data-chat-send="${esc(c)}">${esc(c)}</button>`).join('')}</div>`;appendMessage('assistant',content);history.push({role:'assistant',content:reply.text});
 }catch{if(current===chatVersion){loading.remove();appendMessage('assistant','<p>这次回复没有完成，请重试。</p><button class="outline-button" data-chat-send="'+esc(text)+'">重试</button>')}}finally{if(current===chatVersion){chatBusy=false;document.getElementById('chat-submit').disabled=false;document.getElementById('chat-messages').scrollTop=document.getElementById('chat-messages').scrollHeight}}}
function savePlan(id){const p=pendingPlans.get(id);if(!p)return;const i=state.plans.findIndex(x=>x.id===id);if(i>=0)state.plans[i]=structuredClone(p);else state.plans.push(structuredClone(p));persist();document.querySelectorAll('[data-save-plan]').forEach(b=>{if(b.dataset.savePlan===id)b.innerHTML=icon('check')+' 已保存到我的方案'});toast('已保存，可在“我的”中查看和继续调整');render()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b)return;const d=b.dataset;
 if(b.classList.contains('brand')){e.preventDefault();navigate('home')}
 else if(d.page)navigate(d.page);
 else if(b.hasAttribute('data-chat'))openChat(d.chat);
 else if(d.foodTab){foodTab=d.foodTab;navigate('food')}
 else if(d.careTab){careTab=d.careTab;render()}
 else if(d.homeMode){homeMode=d.homeMode;render()}
 else if(d.day){day=d.day;render()}
 else if(d.recipe)recipeDetail(d.recipe);
 else if(d.topic)topicDetail(d.topic);
 else if(d.article)articleDetail(d.article);
 else if(d.lifestyle)lifestyleDetail();
 else if(d.close)(d.close==='chat'?chat:detail).close();
 else if(d.detailChat)openChat(d.detailChat);
 else if(d.chatSend)send(d.chatSend);
 else if(d.chatRecipe){chat.close();recipeDetail(d.chatRecipe)}
 else if(d.chatTopic){chat.close();topicDetail(d.chatTopic)}
 else if(b.hasAttribute('data-chat-constitution')){chat.close();constitutionList()}
 else if(d.save)toggleSave(d.save);
 else if(d.savePlan)savePlan(d.savePlan);
 else if(d.removePlan){state.plans=state.plans.filter(x=>x.id!==d.removePlan);persist();render();toast('已移除这份演示方案')}
 else if(b.hasAttribute('data-quiz-answer')){quizAnswers[quizStep]=Number(d.quizAnswer);quizStep++;quiz()}
 else if(d.action){switch(d.action){case'about':about();break;case'edit-profile':editProfile();break;case'constitutions':constitutionList();break;case'quiz':quizStep=0;quizAnswers=[];quiz();break;case'quiz-back':quizStep=Math.max(0,quizStep-1);quiz();break;case'save-quiz':state.profile.constitution='平和质';state.profile.updated=new Date().toISOString();persist();detail.close();navigate('profile');toast('已保存模拟体质卡，非真实测评结果');break;case'new-chat':chatVersion++;chatBusy=false;chatScenario='general';history=[];pendingPlans.clear();document.getElementById('chat-content').innerHTML='';openChat();break;case'reset':openDetail('<div class="detail-body"><h2>清除本地演示数据？</h2><p class="detail-lead">将清除当前浏览器中的档案、收藏和方案，恢复初始体验。</p><div class="button-row"><button class="outline-button" data-close="detail">先保留</button><button class="primary-button" data-action="confirm-reset">确认清除</button></div></div>','清除演示数据');break;case'confirm-reset':state={profile:{...defaultProfile},saved:[],plans:[]};persist();chatVersion++;chatBusy=false;history=[];chatScenario='general';pendingPlans.clear();document.getElementById('chat-content').innerHTML='';detail.close();navigate('profile');toast('已恢复初始体验');break}}
});
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();const f=new FormData(e.target);state.profile={...state.profile,name:String(f.get('name')).trim().slice(0,20)||'体验用户',goal:String(f.get('goal')),habit:String(f.get('habit')),preference:String(f.get('preference')),updated:new Date().toISOString()};persist();detail.close();render();toast('档案已保存，示例将沿用你的目标和偏好')}else if(e.target.id==='chat-form'){e.preventDefault();send(document.getElementById('chat-input').value)}});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(e.target.value)}});
for(const dialog of[detail,chat])dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
let width=innerWidth;window.addEventListener('resize',()=>{if((width<=760)!==(innerWidth<=760)){document.querySelector('.topbar-label').textContent=innerWidth<=760?'知养':'你的日常食养空间'}width=innerWidth});
page=['home','food','care','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();historyAPI(true);
// Optional WebMCP exposes the same navigation and read-only demo overview as the visible UI.
const context=document.modelContext;
if(context?.registerTool){const life=new AbortController();const tools=[{name:'get_wellness_demo_overview',title:'读取知养演示概览',description:'Read the current demo page and counts of saved plans and content. Does not expose chat or personal profile data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return{page,mode:'mock',savedPlans:state.plans.length,savedItems:state.saved.length}}},{name:'navigate_wellness_demo',title:'切换知养演示页面',description:'Navigate to an existing demo page. Does not send a message, assess health, or save a plan.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['home','food','care','profile']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['home','food','care','profile'].includes(input.page))throw new Error('Invalid page');navigate(input.page);return{page}}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
